"""Same window, but the cut may not land between a tool call and its result."""

MAX_MESSAGES = 100


def record_tool_result(messages, tool_use_id, output):
    messages.append({
        "role": "user",
        "content": [{"type": "tool_result", "tool_use_id": tool_use_id, "content": output}],
    })
    return messages


def _issued_ids(kept):
    ids = set()
    for message in kept:
        for block in message.get("content", []):
            if isinstance(block, dict) and block.get("type") == "tool_use":
                ids.add(block["id"])
    return ids


def _drop_orphan_results(kept):
    # Advance the cut while the first kept message answers a call we dropped.
    while kept:
        issued = _issued_ids(kept)
        heads = [b for b in kept[0].get("content", [])
                 if isinstance(b, dict) and b.get("type") == "tool_result"]
        if any(b["tool_use_id"] not in issued for b in heads):
            kept = kept[1:]
            continue
        return kept
    return kept


def trim_to_window(messages):
    return _drop_orphan_results(messages[-MAX_MESSAGES:])


def build_request(messages, model):
    return {"model": model, "max_tokens": 1024, "messages": trim_to_window(messages)}
